// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _target, uint256 _value, bytes memory _data) public {
        // Capture the owner before calling sendMoney
        address ownerBefore = c.owner();

        // Call sendMoney with the current owner as msg.sender (the deployer)
        vm.prank(c.owner());
        (bool success, ) = address(c).call{value: 0}(
            abi.encodeWithSignature("sendMoney(address,uint256,bytes)", _target, _value, _data)
        );

        // Rule: After any sendMoney call, the owner must remain unchanged (same as before)
        assertTrue(c.owner() == ownerBefore);
    }
}

